```openscad
// Round-bottom flask support ring on three legs
// Units: mm

// ---------- Parameters ----------
ring_od        = 70;    // ring outer diameter
ring_id        = 50;    // ring inner diameter
ring_thick     = 4;     // ring thickness
ring_top_z     = 50;    // z of ring top face

leg_d          = 6;     // leg diameter
leg_circle_d   = 60;    // diameter of circle on which leg axes lie
leg_count      = 3;     // number of legs
leg_start_ang  = 0;     // first leg on +X axis (degrees)
leg_overlap    = 1;     // how far legs extend into ring for a solid union

cut_ext        = 0.5;   // cutter extension past faces

$fn = 96;

// ---------- Derived ----------
ring_bot_z = ring_top_z - ring_thick;   // z of ring bottom face

// ---------- Model ----------
union() {
    // Ring (annulus)
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -cut_ext])
                cylinder(d = ring_id, h = ring_thick + 2 * cut_ext);
        }

    // Legs
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + leg_overlap);
    }
}
```

