// Spacer with counterbored through-hole for a socket-head screw
// Print orientation: standing on the bed, z = 0 to 15, centred on origin

$fn = 96;                 // facet count for curved surfaces

// --- Dimensions (mm) ---
spacer_d      = 18;       // outer diameter of spacer
spacer_h      = 15;       // total height of spacer
hole_d        = 4.5;      // through-hole diameter
cbore_d       = 8;        // counterbore diameter
cbore_depth   = 3;        // counterbore depth from top face (z = 12 to 15)
eps           = 0.5;      // overcut past faces to avoid coplanar surfaces

difference() {
    // Main body
    cylinder(d = spacer_d, h = spacer_h);

    // Through-hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = spacer_h + 2 * eps);

    // Counterbore from the top face
    translate([0, 0, spacer_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
```

