```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail on top

// ---------------- Parameters ----------------
plate_len   = 60;   // base plate length (X)
plate_wid   = 30;   // base plate width (Y)
plate_thk   = 5;    // base plate thickness (Z), z = 0..5

rail_len    = 60;   // rail length (X), full plate length
rail_bot_w  = 8;    // rail width at plate surface (z = 5)
rail_top_w  = 14;   // rail width at top face (z = 10)
rail_h      = 5;    // rail height above plate (z = 5..10)

overlap     = 0.01; // small overlap to fuse rail into plate

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // Polygon drawn in (Y, Z); rotate so extrusion axis becomes X
    translate([-rail_len/2, 0, 0])
        rotate([90, 0, 90])
            linear_extrude(height = rail_len)
                polygon(points = [
                    [-rail_bot_w/2, plate_thk - overlap],
                    [ rail_bot_w/2, plate_thk - overlap],
                    [ rail_top_w/2, plate_thk + rail_h],
                    [-rail_top_w/2, plate_thk + rail_h]
                ]);
}
```

