```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------- Base plate ----------
plate_len   = 60;   // X length of base plate
plate_wid   = 30;   // Y width of base plate
plate_thk   = 6;    // Z thickness of base plate (z = 0 .. 6)

// ---------- Dovetail rail ----------
rail_len      = plate_len; // rail runs full length of plate (X)
rail_base_w   = 10;        // rail width where it meets plate (at z = plate_thk)
rail_top_w    = 16;        // rail width at top face
rail_top_z    = 14;        // absolute Z of rail top face
rail_overlap  = 0.5;       // rail extends this far down into plate for a solid union

// ---------- Derived ----------
rail_h = rail_top_z - plate_thk; // rail height above plate (8 mm)
// Half-width of the rail extended downward into the plate, following the same flare
rail_overlap_hw = rail_base_w/2 - ((rail_top_w - rail_base_w)/2) * (rail_overlap / rail_h);

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // 2D profile in (Y, Z); extruded along X, centred on origin
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_overlap_hw, plate_thk - rail_overlap],
                [ rail_overlap_hw, plate_thk - rail_overlap],
                [ rail_top_w/2,    rail_top_z],
                [-rail_top_w/2,    rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
