```openscad
// Weighted base for a lab stand rod
// Print orientation: disc flat on bed, boss pointing up (+Z)

$fn = 96;

// ---- Dimensions (mm) ----
disc_d      = 100;   // base disc diameter
disc_h      = 6;     // base disc thickness (z = 0 to 6)
boss_d      = 24;    // boss outer diameter
boss_top_z  = 31;    // top of boss (boss rises from z = 6 to z = 31)
rod_hole_d  = 12.5;  // rod hole diameter
floor_t     = 2;     // closed floor under the rod hole (hole bottom at z = 2)
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Coaxial boss, slightly overlapping the disc for a clean union
        translate([0, 0, disc_h - 0.01])
            cylinder(d = boss_d, h = boss_top_z - disc_h + 0.01);
    }
    // Rod hole from top of boss down to 2 mm above the bed
    translate([0, 0, floor_t])
        cylinder(d = rod_hole_d, h = boss_top_z - floor_t + eps);
}
