// Door wedge - right-angled wedge with a vertical through-slot
// Units: mm. Print orientation: flat base on XY plane, builds up +Z.
// Positioned per the user's coordinates (x 0..120, y 0..35), not centred.

// ---------- Wedge dimensions ----------
wedge_length = 120;   // X length of base (hypotenuse runs from x=0,z=25 to x=120,z=0)
wedge_width  = 35;    // Y width (extrusion depth)
wedge_height = 25;    // Z height at the tall end (x = 0)

// ---------- Slot dimensions ----------
slot_width    = 8;    // slot size along Y
slot_length   = 30;   // slot size along X
slot_center_x = 60;   // slot centre X
slot_center_y = 17.5; // slot centre Y
cut_margin    = 1;    // extra length so cuts pass fully through faces

$fn = 64;

difference() {
    // Wedge body: right-triangle profile in XZ, extruded along Y from 0 to 35
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);

    // Vertical straight slot through the whole wedge
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -cut_margin])
        cube([slot_length, slot_width, wedge_height + 2 * cut_margin]);
}
