// Glass stirring rod rest: rectangular block with 3 V-grooves across the top

// ---- Block dimensions ----
block_len   = 64;    // length along X (mm)
block_wid   = 30;    // width along Y (mm)
block_ht    = 12;    // height along Z (mm)

// ---- Groove dimensions ----
groove_count = 3;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_top_w = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth (mm), 90-degree V (half width = depth)

// ---- Cutting overlap ----
eps = 0.5;           // extension past cut faces (mm)

$fn = 64;

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running the full width along Y
    for (i = [0 : groove_count - 1]) {
        x_c = (i - (groove_count - 1) / 2) * groove_pitch;
        translate([x_c, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height = block_wid + 2*eps, center = true)
                    // 90-degree V: sides extended by eps above the top face
                    polygon([
                        [-(groove_top_w/2 + eps), block_ht + eps],
                        [ (groove_top_w/2 + eps), block_ht + eps],
                        [ 0, block_ht - groove_depth]
                    ]);
    }
}
