// Glass stirring rod rest - rectangular block with V-grooves across the top

// ---------- Block ----------
block_len   = 92;   // length along X (mm)
block_wid   = 40;   // width along Y (mm)
block_h     = 18;   // height along Z (mm)

// ---------- V-grooves ----------
groove_count = 5;   // number of grooves
groove_pitch = 18;  // centre-to-centre spacing along X (mm)
groove_top_w = 10;  // groove width at top surface (mm)
groove_depth = 5;   // groove depth (mm) -> 90 deg V (half-width = depth)

// ---------- Helpers ----------
eps     = 0.5;      // overshoot for clean boolean cuts (mm)
$fn     = 64;

// X positions of grooves, centred on origin
function groove_x(i) = (i - (groove_count - 1) / 2) * groove_pitch;

// 2D V profile in the X-Z plane, extended above the top surface along the
// same 45 deg flanks so the cut has no coplanar faces
module v_profile() {
    polygon(points = [
        [0, block_h - groove_depth],                     // V tip
        [ groove_top_w / 2 + eps, block_h + eps],        // right flank, above top
        [-groove_top_w / 2 - eps, block_h + eps]         // left flank, above top
    ]);
}

// One groove running the full width along Y (with overshoot)
module groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            v_profile();
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves
    for (i = [0 : groove_count - 1])
        translate([groove_x(i), 0, 0])
            groove();
}
