slope    = half_top / groove_depth;          // 1.0 for a 90-degree V
ext_half = half_top + overcut * slope;       // half-width at z = top + overcut

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_l / 2, -block_w / 2, 0])
        cube([block_l, block_w, block_h]);

    // V-grooves running the full width along Y, centred along X
    for (i = [0 : groove_count - 1]) {
        gx = (i - (groove_count - 1) / 2) * groove_pitch;
        translate([gx, 0, block_h])
            rotate([90, 0, 0])
                linear_extrude(height = block_w + 2 * overcut, center = true)
                    polygon(points = [
                        [0, -groove_depth],      // V bottom
                        [ ext_half, overcut],    // extended above top face
                        [-ext_half, overcut]
                    ]);
    }
}
