// Captive hex-nut clamping block
// Print orientation: bottom face (with hex pocket) on the bed, z = 0

// ---------------- Parameters ----------------
block_x      = 20;     // block length in X (mm)
block_y      = 24;     // block width in Y (mm)
block_z      = 12;     // block height in Z (mm)

hole_d       = 3.4;    // through-hole diameter (mm)

hex_flats    = 5.6;    // hex pocket size across flats (mm)
hex_depth    = 2.6;    // hex pocket depth from bottom face (mm)

eps          = 0.5;    // overshoot for clean boolean cuts (mm)
hole_fn      = 64;     // facets for round hole

// Derived: circumradius of hexagon (across corners / 2)
hex_r = hex_flats / (2 * cos(30));

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2*eps, $fn = hole_fn);

    // Hex nut pocket from bottom face.
    // $fn = 6 puts vertices on the X axis, so two flats are parallel to X.
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
