// Cross-shaped bottle stabiliser
// Flat plus-sign plate, printed lying flat on the bed

// ---------------- Parameters ----------------
plate_thickness = 4;     // plate thickness (Z)
arm_length      = 70;    // overall length of each bar (tip to tip)
arm_width       = 10;    // width of each bar
hole_d          = 4.5;   // diameter of all through-holes
end_hole_offset = 30;    // distance from origin to arm-end hole centres
cut_extra       = 0.5;   // overshoot for cutting shapes past faces
$fn             = 64;    // circle resolution

// ---------------- Model ----------------
difference() {
    // Plus-sign body
    union() {
        // Bar along X
        translate([-arm_length/2, -arm_width/2, 0])
            cube([arm_length, arm_width, plate_thickness]);
        // Bar along Y
        translate([-arm_width/2, -arm_length/2, 0])
            cube([arm_width, arm_length, plate_thickness]);
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thickness + 2*cut_extra, $fn = $fn);

    // Arm-end holes (+X, +Y, -X, -Y)
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([end_hole_offset, 0, -cut_extra])
                cylinder(d = hole_d, h = plate_thickness + 2*cut_extra, $fn = $fn);
}
