```openscad
// Stepped riser: solid staircase of 4 equal steps
// Print orientation: rests on the bed (z = 0) and builds upward in +Z.
// The profile is drawn in the XZ plane and climbs in +X.
// It is extruded along Y from y = 0 to y = 40.

// ---------- Parameters ----------
n_steps     = 4;    // number of steps
step_len    = 12;   // length of each step along X (mm)
step_rise   = 8;    // height increase per step (mm); first step is 8 mm tall
riser_depth = 40;   // extrusion length along Y (mm), y = 0 .. 40

// ---------- Derived ----------
total_len = n_steps * step_len;    // 48 mm
top_h     = n_steps * step_rise;   // 32 mm

// Staircase profile in the XZ plane (polygon x = X, polygon y = Z).
// Points run from the origin, up and across each step, then down to the bed.
profile_pts = concat(
    [[0, 0]],
    [for (i = [0 : n_steps - 1]) each [
        [i * step_len,       (i + 1) * step_rise],   // top-left corner of step i
        [(i + 1) * step_len, (i + 1) * step_rise]    // top-right corner of step i
    ]],
    [[total_len, 0]]
);

// ---------- Model ----------
// rotate([90,0,0]) turns polygon y into +Z and the extrusion direction into -Y.
// The translate then shifts the part so it spans y = 0 .. riser_depth.
translate([0, riser_depth, 0])
    rotate([90, 0, 0])
        linear_extrude(height = riser_depth)
            polygon(points = profile_pts);
```

