step_len    = 15;   // length of each step along X (mm)
step_rise   = 8;    // height increase per step (mm)
depth_y     = 20;   // extrusion depth along Y (mm)

total_len   = n_steps * step_len;   // 45 mm
total_h     = n_steps * step_rise;  // 24 mm

// Each step is a solid block from the bed up to its tread height.
// Blocks overlap slightly in X so the union is one clean solid.
overlap     = 0.01; // small overlap between adjacent blocks (mm)

union() {
    for (i = [0 : n_steps - 1]) {
        x0 = i * step_len;
        x_ext = (i < n_steps - 1) ? overlap : 0;
        translate([x0, 0, 0])
            cube([step_len + x_ext, depth_y, (i + 1) * step_rise]);
    }
}
